components.css:
.ds-btn-outlined { font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; font-size: 12px; font-weight: 600; letter-spacing: 0; color: #101010; background: transparent; border: 1px solid rgba(16,16,16,0.34); border-radius: 0; min-height: 26px; padding: 0 10px; cursor: pointer; }
.ds-btn-outlined:hover { border-color: #101010; background: rgba(16,16,16,0.04); }
.ds-btn-outlined:focus-visible { outline: 2px solid #0093d0; outline-offset: 1px; }

.ds-btn-contained { font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; font-size: 12px; font-weight: 600; letter-spacing: 0; color: #ffffff; background: #101010; border: 1px solid #101010; border-radius: 0; min-height: 26px; padding: 0 10px; cursor: pointer; }
.ds-btn-contained:hover { background: #000000; border-color: #000000; }
.ds-btn-contained:focus-visible { outline: 2px solid #0093d0; outline-offset: 1px; }

.ds-btn-text { font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; font-size: 12px; font-weight: 600; letter-spacing: 0; color: rgba(16,16,16,0.62); background: transparent; border: 1px solid transparent; border-radius: 0; min-height: 26px; padding: 0 8px; cursor: pointer; }
.ds-btn-text:hover { border-color: #101010; background: rgba(16,16,16,0.04); }
.ds-btn-text:focus-visible { outline: 2px solid #0093d0; outline-offset: 1px; }

.ds-input { display: inline-flex; align-items: center; background: #ffffff; border: 1px solid rgba(16,16,16,0.34); border-radius: 0; padding: 6px 9px; }
.ds-input-control { width: 100%; min-width: 0; border: 0; outline: none; background: transparent; color: #101010; font-family: 'Cascadia Mono', Consolas, 'DejaVu Sans Mono', Menlo, monospace; font-size: 13px; }
.ds-input-suffix { font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; font-size: 10.5px; color: rgba(16,16,16,0.62); margin-left: 4px; }
.ds-input:hover { border-color: #101010; }
.ds-input:focus-within { border-color: #101010; outline: 2px solid #0093d0; outline-offset: 1px; }
.ds-select { background: #ffffff; color: #101010; font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; font-size: 13px; border: 1px solid rgba(16,16,16,0.34); border-radius: 0; padding: 6px 9px; }
.ds-select:hover { border-color: #101010; }
.ds-select:focus-visible { border-color: #101010; outline: 2px solid #0093d0; outline-offset: 1px; }

.ds-segment { display: inline-flex; border-radius: 0; }
.ds-segment-item { font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; font-size: 12px; font-weight: 600; letter-spacing: 0; color: rgba(16,16,16,0.62); background: transparent; border: 1px solid rgba(16,16,16,0.34); border-radius: 0; padding: 5px 10px; cursor: pointer; }
.ds-segment-item + .ds-segment-item { margin-left: -1px; }
.ds-segment-item:hover { border-color: #101010; }
.ds-segment-item[aria-pressed="true"] { background: #101010; color: #ffffff; }
.ds-segment-item[aria-pressed="true"]:hover { background: #000000; }
.ds-segment-item:focus-visible { outline: 2px solid #0093d0; outline-offset: 1px; position: relative; z-index: 1; }

.ds-field-row { display: grid; grid-template-columns: 96px minmax(0, 1fr); column-gap: 12px; row-gap: 4px; align-items: center; padding: 8px 16px; border-bottom: 1px solid rgba(16,16,16,0.16); background: #ffffff; }
.ds-field-label { font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; font-size: 11.5px; color: rgba(16,16,16,0.62); }
.ds-field-value { min-width: 0; }
.ds-field-hint { grid-column: 2; font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; font-size: 10.5px; line-height: 1.35; color: rgba(16,16,16,0.36); }
.ds-select-inline { width: 100%; background: #ffffff; color: #101010; font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; font-size: 13px; border: 1px solid rgba(16,16,16,0.34); border-radius: 0; padding: 6px 9px; }

.ds-docket-head { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; padding: 6px 16px; background: rgba(16,16,16,0.035); border-top: 1px solid rgba(16,16,16,0.16); border-bottom: 1px solid rgba(16,16,16,0.16); }
.ds-docket-title { font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; font-size: 11.5px; font-weight: 700; color: #101010; }
.ds-docket-meta { font-family: 'Cascadia Mono', Consolas, 'DejaVu Sans Mono', Menlo, monospace; font-size: 10.5px; color: rgba(16,16,16,0.62); }
.ds-docket-foot { display: flex; align-items: center; justify-content: space-between; gap: 16px; padding: 10px 16px; background: rgba(16,16,16,0.02); border-top: 1.5px solid #101010; }
.ds-docket-note { font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; font-size: 10.5px; color: rgba(16,16,16,0.62); }

.ds-state-line { display: flex; align-items: center; gap: 10px; padding: 6px 14px; background: #ffffff; border-top: 1px solid rgba(16,16,16,0.16); }
.ds-state-line-plain { border-top: 0; padding: 4px 0; }
.ds-state-text { font-family: 'Cascadia Mono', Consolas, 'DejaVu Sans Mono', Menlo, monospace; font-size: 11px; color: #101010; }
.ds-state-legend { display: block; padding: 6px 14px; background: #ffffff; }

.ds-stage { position: relative; display: grid; place-content: center; padding: 22px; background: #f4f4f2; }
.ds-reg { position: absolute; display: block; }
.ds-reg-tl { top: 6px; left: 6px; }
.ds-reg-tr { top: 6px; right: 6px; }
.ds-reg-bl { bottom: 6px; left: 6px; }
.ds-reg-br { bottom: 6px; right: 6px; }
.ds-sheet-wrap { display: grid; grid-template-columns: 22px auto; grid-template-rows: 22px auto; }
.ds-ruler-x { display: block; }
.ds-sheet { position: relative; width: 170px; height: 240px; background: #ffffff; box-shadow: 0 1px 1.5px rgba(16,16,16,0.16), 0 18px 34px -18px rgba(16,16,16,0.34); }
.ds-sheet-ink { position: absolute; inset: 0; animation: qrstick-ink 180ms cubic-bezier(0.16, 1, 0.3, 1) both; }
.ds-sheet-placeholder { position: absolute; left: 50%; top: 50%; width: 110px; height: 110px; margin: -55px 0 0 -55px; border: 1px dashed rgba(16,16,16,0.28); }
@keyframes qrstick-ink { from { opacity: 0.42; filter: blur(0.6px); } to { opacity: 1; filter: blur(0); } }
@media (prefers-reduced-motion: reduce) { .ds-sheet-ink { animation: none; } }

.ds-table { background: #ffffff; font-family: 'Segoe UI', 'Microsoft YaHei', 'PingFang SC', 'Noto Sans SC', 'Hiragino Sans GB', sans-serif; }
.ds-table-band { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; padding: 6px 14px; background: rgba(16,16,16,0.035); border-bottom: 1px solid rgba(16,16,16,0.16); }
.ds-table-title { font-size: 11.5px; font-weight: 700; color: #101010; }
.ds-table-readout { font-family: 'Cascadia Mono', Consolas, 'DejaVu Sans Mono', Menlo, monospace; font-size: 10.5px; color: rgba(16,16,16,0.62); }
.ds-table-head, .ds-table-row { display: flex; gap: 12px; padding: 6px 14px; }
.ds-table-head { font-size: 11px; font-weight: 700; color: #101010; border-bottom: 1.5px solid #101010; }
.ds-table-row { font-size: 12px; color: #101010; border-bottom: 1px solid rgba(16,16,16,0.16); cursor: pointer; }
.ds-table-row:hover { background: rgba(16,16,16,0.035); }
.ds-table-row-current { outline: 1px solid #101010; outline-offset: -1px; background: rgba(16,16,16,0.05); font-weight: 600; }
.ds-col-index { width: 68px; text-align: right; font-family: 'Cascadia Mono', Consolas, 'DejaVu Sans Mono', Menlo, monospace; }
.ds-col-mono { flex: 2; font-family: 'Cascadia Mono', Consolas, 'DejaVu Sans Mono', Menlo, monospace; }
.ds-col-text { flex: 1; }
